{
    prism_percentile <- function(x, p) {
        x <- sort(x)
        n <- length(x)
        h <- (n + 1) * p
        if (h <= 1) 
            return(x[1])
        if (h >= n) 
            return(x[n])
        lo <- floor(h)
        x[lo] + (h - lo) * (x[lo + 1] - x[lo])
    }
    whisker_ref <- function(x, whiskers) {
        s <- sort(x)
        q1 <- prism_percentile(s, 0.25)
        q3 <- prism_percentile(s, 0.75)
        if (whiskers == "tukey") {
            lo_fence <- q1 - 1.5 * (q3 - q1)
            hi_fence <- q3 + 1.5 * (q3 - q1)
            low <- NA
            for (v in s) if (v >= lo_fence) {
                low <- v
                break
            }
            high <- NA
            for (v in rev(s)) if (v <= hi_fence) {
                high <- v
                break
            }
        }
        else if (whiskers == "min-max") {
            low <- s[1]
            high <- s[length(s)]
        }
        else {
            p <- switch(whiskers, `p10-90` = 0.1, `p5-95` = 0.05, `p2.5-97.5` = 0.025, 
                `p1-99` = 0.01)
            low <- prism_percentile(s, p)
            high <- prism_percentile(s, 1 - p)
        }
        beyond <- c()
        for (v in s) if (v < low || v > high) 
            beyond <- c(beyond, v)
        list(low = low, high = high, beyond = I(if (is.null(beyond)) numeric(0) else beyond))
    }
    silverman <- function(x) {
        n <- length(x)
        iqr <- diff(quantile(x, c(0.25, 0.75), names = FALSE, type = 7))
        lo <- min(sd(x), iqr/1.34)
        if (!(lo > 0)) 
            lo <- sd(x)
        if (!(lo > 0)) 
            lo <- abs(x[1])
        if (!(lo > 0)) 
            lo <- 1
        0.9 * lo * n^(-0.2)
    }
    kde_ref <- function(x, adjust = 1, log = FALSE) {
        if (log) 
            x <- log10(x[x > 0])
        n <- length(x)
        h <- silverman(x) * adjust
        y <- min(x) + (max(x) - min(x)) * (0:63)/63
        d <- numeric(64)
        for (i in 1:64) {
            s <- 0
            for (xi in x) s <- s + exp(-((y[i] - xi)/h)^2/2)/sqrt(2 * pi)
            d[i] <- s/(n * h)
        }
        list(bw = h, y = I(if (log) 10^y else y), density = I(d))
    }
    cell <- function(x, whiskers = NA, adjust = NA, log = FALSE) {
        out <- list(q1 = prism_percentile(x, 0.25), median = prism_percentile(x, 
            0.5), q3 = prism_percentile(x, 0.75))
        if (!is.na(whiskers)) 
            out$whiskers <- whisker_ref(x, whiskers)
        if (!is.na(adjust)) 
            out$kde <- kde_ref(x, adjust, log)
        out
    }
}
